import { readFileSync } from "node:fs";

import { expect, sample, test, uniqueName } from "../../fixtures";

test(
  "uploading a document returns 201 with status processing and records an audit event",
  { tag: "@DOC-01" },
  async ({ apiAs }) => {
    // Arrange: a vendor in status "draft" owned by the member's tenant
    const member = await apiAs("member");
    const createResponse = await member.post("/api/vendors", {
      data: {
        name: uniqueName("DOC-01 Vendor"),
        category: "services",
        contact_email: "billing@doc01-vendor.test",
      },
    });
    expect(createResponse.status()).toBe(201);
    const vendor = await createResponse.json();
    expect(vendor.status).toBe("draft");

    const fileBuffer = readFileSync(sample("insurance_certificate.txt"));

    // Act: upload the insurance certificate as kind "insurance_certificate"
    const uploadResponse = await member.post(`/api/vendors/${vendor.id}/documents`, {
      multipart: {
        kind: "insurance_certificate",
        file: {
          name: "insurance_certificate.txt",
          mimeType: "text/plain",
          buffer: fileBuffer,
        },
      },
    });

    // Assert: response status and document status
    expect(uploadResponse.status()).toBe(201);
    const document = await uploadResponse.json();
    expect(document.status).toBe("processing");
    expect(document.kind).toBe("insurance_certificate");
    expect(document.vendor_id).toBe(vendor.id);

    // Assert: audit event "document.uploaded" is recorded for the vendor
    const auditResponse = await member.get(`/api/vendors/${vendor.id}/audit`);
    expect(auditResponse.status()).toBe(200);
    const trail = await auditResponse.json();
    const actions = trail.items.map((event: { action: string }) => event.action);
    expect(actions).toContain("document.uploaded");
  },
);
